class SoundScriptManager {
public:
    enum EventType { SS_FE_LEFTRIGHT = 26 };
    static SoundScriptManager *instance;
    static SoundScriptManager *inst() { return instance; }
    void unpause();
    void playEvent(EventType, void * = 0, float = 0.0f);
    void pause();
};

struct PanelFile {
    char padding[0x88];
    int slide_state;
    bool IsSliding() const { return slide_state == 1 || slide_state == 2; }
};

class BeachFrontEndPadding {
protected:
    char padding0[0x4c];
    FEMenuEntry *highlighted;
    char padding1[0x74 - 0x50];
};

class BeachFrontEnd : public BeachFrontEndPadding, public FEMenu {
    PanelFile panel;
    char padding1[0x158 - 0x104];
    FEMenuEntry *secondary_cursor;
    char padding2[0x894 - 0x15c];
    FEMenuEntry *fe_return;
    char padding3[0x8fc - 0x898];
    FEMenuEntry *yes_entry;
    FEMenuEntry *no_entry;
    char padding4[0x920 - 0x904];
    int in_description_mode;
    int in_bio_mode;
    char padding5[0xf08 - 0x928];
    int in_frontend;
    char padding6[0xf1c - 0xf0c];
    int ignore_controller;

public:
    void OnRight(int);
    void SwitchBeach(bool);
    void UpdateBeach(bool);
};

void BeachFrontEnd::OnRight(int c)
{
	if((ignore_controller || panel.IsSliding()) && !in_frontend) return;
	if(in_description_mode || in_bio_mode) return;
	if (!in_frontend)
		SoundScriptManager::inst()->unpause();

	SoundScriptManager::inst()->playEvent(SoundScriptManager::SS_FE_LEFTRIGHT);
	if (!in_frontend)
		SoundScriptManager::inst()->pause();

	if(!in_frontend && fe_return == highlighted)
	{
		if(secondary_cursor == yes_entry)
			SetSecondaryCursor(no_entry);
		else SetSecondaryCursor(yes_entry);
		return;
	}


	SwitchBeach(true);
	UpdateBeach(true);
}
